function parDoAlvo(numeros, alvo) {
  const vistos = new Map();
  for (let i = 0; i < numeros.length; i++) {
    const complemento = alvo - numeros[i];
    if (vistos.has(complemento)) {
      return [vistos.get(complemento), i];
    }
    vistos.set(numeros[i], i);
  }
  return [];
}

